void is_sms_rev_unread(char * dir_path,char * file_path)
{
    FILE *          p_file;
    size_t          read_len;
    tele_sms_storge_rev_param_t sms_sim_resp;

    if (strcmp(TELE_SMS_DATA_REV_FOLDER_PATH,dir_path) != 0)
        return;

    read_len = sizeof(tele_sms_storge_rev_param_t)-4;

    p_file              = fopen(file_path,"rb");

    if (p_file == NULL) {
        __inf("p_file==NULL\r\n");
        return;
        }

    fread(&sms_sim_resp,1,read_len,p_file);
    fclose(p_file);


    if(sms_sim_resp.param.base_info.err_code == 0)
        tele_sms_rev_unread_count_minus();

}


void sms_del_select_file(char * path,uint32_t * p_file_index,uint32_t count)
{
    size_t          path_len;
    char *          full_path;
    DIR *           dir;

    struct stat stat_entry;
    struct dirent * entry;
    int32_t         result = 1;
    uint32_t        i   = 0;

    if ((dir = opendir(path)) == NULL) {
        __inf("app_fs_remove_folder: unable to opendir %s\n",path);
        return;
        }

    /* the length of the path */
    path_len            = strlen(path);

    /* iteration through entries in the directory */
    while ((entry = readdir(dir)) != NULL) {
#if 0

        /* skip entries "." and ".." */
        if (!strcmp(entry->d_name,".") || !strcmp(entry->d_name,".."))
            continue;

#endif

        /* determinate a full path of an entry */
        full_path           = lv_mem_alloc(path_len + strlen(entry->d_name) + 2);

        if (full_path) {
            strcpy(full_path,path);
            strcat(full_path,"/");
            strcat(full_path,entry->d_name);

            /* stat for the entry */
            if (-1 != stat(full_path,&stat_entry)) {
                /* recursively remove a nested directory */
                if (S_ISDIR(stat_entry.st_mode) != 0) {

                    }
                else {
                    __inf("sms_del_select_file p_file_index:%d,%d,%d",i,p_file_index[i],telldir(dir));

                    if (p_file_index[i] == telldir(dir)) {
                        is_sms_rev_unread(path,full_path);

                        if (unlink(full_path) == 0) {
                            __inf("sms_del_select_file sucess:%d,%d,%s",i,telldir(dir),full_path);
                            sms_data_box_count_reduce(path);
                            }
                        else {
                            __inf("sms_del_select_file failed:%d,%d,%s",i,telldir(dir),full_path);

                            }
                        }
                    }
                }

            lv_mem_free(full_path);

            if (!result) {
                break;
                }
            }
        else {
            result              = 0;
            __inf("app_fs_remove_folder: no memory\n");
            break;
            }

        i++;
        }

    closedir(dir);

    __inf("sms_del_select_file result:%d\n",result);
}






static void sms_del_select_file_action(lv_obj_t * ui_Screen)
{
    uint32_t *      p_file_index,*p_file_index_tmp;
    uint32_t        count;

    ui_screen_sms_del_select_obj_t * p_screen_param;

    /***********************************************************************/
    /********
    ui显示为倒序（显示最新的消息）
    因此要把顺序倒成fatfs存储的顺序进行删除
    **********/
    p_screen_param      = (ui_screen_sms_del_select_obj_t *) lv_obj_get_user_data(ui_Screen);
    p_file_index_tmp    = p_screen_param->p_enter_param->p_file_index;
    count               = p_screen_param->p_enter_param->file_count;
    p_file_index        = lv_mem_alloc(count * 4);
    memset(p_file_index,0,count * 4);

    if (p_file_index == NULL) {
        __inf("sms_del_select_file_action p_file_index==NULL");
        }

    for (int i = 0; i < count; i++) {
        p_file_index[i]     = p_file_index_tmp[count - 1 - i];
        }

    /***********************************************************************/
    sms_del_select_file(p_screen_param->p_enter_param->path,p_file_index,count);
    lv_mem_free(p_file_index);
}


